// Debugging checklist: reproduce, isolate, read the stack trace, fix, add a test
// Safe recursion: a trampoline turns deep recursion into a loop
const trampoline = (fn) => (...args) => {
  let result = fn(...args);
  while (typeof result === 'function') result = result();
  return result;
};

const sumTo = trampoline(function sum(n, acc = 0) {
  return n === 0 ? acc : () => sum(n - 1, acc + n);
});

console.log(sumTo(1000000)); // no stack overflow

