// api.test.js: four slices, four checks (Node 18+, no dependencies)
const base = 'http://localhost:3000';
const slices = [
  ['GET', '/health', 200],
  ['GET', '/api/users', 200],
  ['POST', '/api/login', 400],
  ['GET', '/does-not-exist', 404]
];
for (const [method, path, expected] of slices) {
  const response = await fetch(base + path, { method });
  console.log(response.status === expected ? 'PASS' : 'FAIL', method, path, response.status);
}

class AppError extends Error {
  constructor(message, { cause, code } = {}) {
    super(message, { cause });
    this.name = 'AppError';
    this.code = code;
  }
}

try {
  JSON.parse('{ broken json');
} catch (error) {
  const wrapped = new AppError('Could not read the config', { cause: error, code: 'CONFIG_PARSE' });
  console.error(wrapped.stack);
  console.error('Caused by:', wrapped.cause.message);
}

// A toy hash chain: each block stores the hash of the previous one
const { createHash } = require('crypto');
const hash = (data) => createHash('sha256').update(data).digest('hex');

const chain = [{ index: 0, data: 'genesis', prev: '0', hash: hash('genesis') }];
function addBlock(data) {
  const prev = chain[chain.length - 1];
  const block = { index: prev.index + 1, data, prev: prev.hash };
  block.hash = hash(block.index + block.data + block.prev);
  chain.push(block);
}
addBlock('vanilla');
addBlock('berries');
console.log(chain);

