app.listen(3000, () => console.log('Back-end on http://localhost:3000'));

export const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export function debounce(fn, wait = 300) {
  let timer;
  return (...args) => { clearTimeout(timer); timer = setTimeout(() => fn(...args), wait); };
}

export function throttle(fn, wait = 300) {
  let last = 0;
  return (...args) => { const now = Date.now(); if (now - last >= wait) { last = now; fn(...args); } };
}

// handler.js: serverless HTTP function
export const handler = async (event) => {
  const name = event.queryStringParameters?.name ?? 'cloud dev';
  return {
    statusCode: 200,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ message: `Hello, ${name}!`, at: new Date().toISOString() })
  };
};
